ALTER TABLE accounts ADD COLUMN IF NOT EXISTS pin_failed_attempts INTEGER DEFAULT 0 NOT NULL;
ALTER TABLE accounts ADD COLUMN IF NOT EXISTS pin_locked_until TIMESTAMP(6) WITH TIME ZONE;
ALTER TABLE transactions ADD COLUMN IF NOT EXISTS transaction_nonce VARCHAR(64) UNIQUE;
ALTER TABLE transactions ADD COLUMN IF NOT EXISTS rejection_reason VARCHAR(64);
CREATE TABLE IF NOT EXISTS app_users (id UUID PRIMARY KEY, name VARCHAR(80) NOT NULL, email VARCHAR(254) NOT NULL UNIQUE, phone VARCHAR(18) NOT NULL UNIQUE, phone_normalized VARCHAR(18), password_hash VARCHAR(100) NOT NULL, upi_id VARCHAR(80) NOT NULL UNIQUE, recipient_discoverable BOOLEAN DEFAULT FALSE NOT NULL, recipient_version INTEGER DEFAULT 1 NOT NULL, recipient_updated_at TIMESTAMP(6) WITH TIME ZONE, created_at TIMESTAMP(6) WITH TIME ZONE NOT NULL, offline_payment_limit DECIMAL(12,2) DEFAULT 0.00 NOT NULL, hide_balance BOOLEAN DEFAULT FALSE NOT NULL, hide_transaction_details BOOLEAN DEFAULT FALSE NOT NULL, account_locked BOOLEAN DEFAULT FALSE NOT NULL, account_locked_at TIMESTAMP(6) WITH TIME ZONE, app_lock_enabled BOOLEAN DEFAULT FALSE NOT NULL, app_lock_type VARCHAR(12), app_lock_password_hash VARCHAR(100), app_lock_failed_attempts INTEGER DEFAULT 0 NOT NULL, app_lock_locked_until TIMESTAMP(6) WITH TIME ZONE);
CREATE TABLE IF NOT EXISTS app_sessions (token_hash VARCHAR(64) PRIMARY KEY, user_id VARCHAR(36) NOT NULL, expires_at TIMESTAMP(6) WITH TIME ZONE NOT NULL, device_id VARCHAR(64), app_lock_verified BOOLEAN DEFAULT FALSE NOT NULL, app_lock_verified_at TIMESTAMP(6) WITH TIME ZONE);
ALTER TABLE app_sessions ADD COLUMN IF NOT EXISTS app_lock_verified BOOLEAN DEFAULT FALSE NOT NULL;
ALTER TABLE app_sessions ADD COLUMN IF NOT EXISTS app_lock_verified_at TIMESTAMP(6) WITH TIME ZONE;
CREATE TABLE IF NOT EXISTS linked_bank_accounts (id UUID PRIMARY KEY, owner_user_id UUID NOT NULL, bank_name VARCHAR(100) NOT NULL, account_holder_name VARCHAR(512) NOT NULL, masked_account_number VARCHAR(20) NOT NULL, account_fingerprint VARCHAR(64), verify_attempts INTEGER DEFAULT 0 NOT NULL, verification_status VARCHAR(16) NOT NULL, verification_mode VARCHAR(24) NOT NULL, verification_message VARCHAR(300), provider_reference VARCHAR(100), created_at TIMESTAMP(6) WITH TIME ZONE NOT NULL, updated_at TIMESTAMP(6) WITH TIME ZONE NOT NULL, CONSTRAINT uk_linked_bank_owner_fingerprint UNIQUE(owner_user_id, account_fingerprint));
ALTER TABLE linked_bank_accounts ADD COLUMN IF NOT EXISTS account_fingerprint VARCHAR(64);
ALTER TABLE linked_bank_accounts ADD COLUMN IF NOT EXISTS verify_attempts INTEGER DEFAULT 0 NOT NULL;
CREATE TABLE IF NOT EXISTS bank_otp_challenges (id UUID PRIMARY KEY, owner_user_id UUID NOT NULL, created_at TIMESTAMP(6) WITH TIME ZONE NOT NULL, expires_at TIMESTAMP(6) WITH TIME ZONE NOT NULL, resend_after TIMESTAMP(6) WITH TIME ZONE NOT NULL, attempts INTEGER NOT NULL, otp_hash VARCHAR(64), send_count INTEGER DEFAULT 1 NOT NULL, verified BOOLEAN NOT NULL, verified_at TIMESTAMP(6) WITH TIME ZONE, consumed BOOLEAN NOT NULL, version BIGINT NOT NULL);
ALTER TABLE bank_otp_challenges ADD COLUMN IF NOT EXISTS send_count INTEGER DEFAULT 1 NOT NULL;
ALTER TABLE bank_otp_challenges ADD COLUMN IF NOT EXISTS verified_at TIMESTAMP(6) WITH TIME ZONE;
CREATE TABLE IF NOT EXISTS password_challenges (id UUID PRIMARY KEY, user_id VARCHAR(36), email_key VARCHAR(64) NOT NULL, requester_key VARCHAR(64), purpose VARCHAR(12) NOT NULL, otp_hash VARCHAR(100), otp_expires_at TIMESTAMP(6) WITH TIME ZONE, reset_token_hash VARCHAR(64), reset_expires_at TIMESTAMP(6) WITH TIME ZONE, attempts INTEGER NOT NULL, otp_consumed BOOLEAN NOT NULL, reset_consumed BOOLEAN NOT NULL, created_at TIMESTAMP(6) WITH TIME ZONE NOT NULL, expires_at TIMESTAMP(6) WITH TIME ZONE NOT NULL);
ALTER TABLE password_challenges ALTER COLUMN purpose VARCHAR(12) NOT NULL;
CREATE TABLE IF NOT EXISTS trusted_devices (id UUID PRIMARY KEY, owner_user_id UUID NOT NULL, device_id VARCHAR(36) NOT NULL, device_name VARCHAR(80) NOT NULL, platform VARCHAR(16) NOT NULL, verification_method VARCHAR(32) NOT NULL, registered_at TIMESTAMP(6) WITH TIME ZONE NOT NULL, last_active_at TIMESTAMP(6) WITH TIME ZONE NOT NULL, revoked_at TIMESTAMP(6) WITH TIME ZONE, CONSTRAINT uk_trusted_device_owner_id UNIQUE(owner_user_id, device_id));
CREATE TABLE IF NOT EXISTS notification_push_tokens (id UUID PRIMARY KEY, owner_user_id UUID NOT NULL, expo_push_token VARCHAR(255) NOT NULL UNIQUE, enabled BOOLEAN NOT NULL, sound_enabled BOOLEAN NOT NULL, updated_at TIMESTAMP(6) WITH TIME ZONE NOT NULL);
CREATE TABLE IF NOT EXISTS user_notifications (id UUID PRIMARY KEY, recipient_user_id UUID NOT NULL, transaction_id BIGINT NOT NULL UNIQUE, sender_name VARCHAR(80) NOT NULL, amount DECIMAL(19,2) NOT NULL, payment_status VARCHAR(16) NOT NULL, created_at TIMESTAMP(6) WITH TIME ZONE NOT NULL, read_at TIMESTAMP(6) WITH TIME ZONE);
CREATE TABLE IF NOT EXISTS account_deletion_requests (id UUID PRIMARY KEY, user_id UUID NOT NULL, request_created_at TIMESTAMP(6) WITH TIME ZONE NOT NULL, scheduled_deletion_at TIMESTAMP(6) WITH TIME ZONE NOT NULL, status VARCHAR(24) NOT NULL, cancelled_at TIMESTAMP(6) WITH TIME ZONE, deleted_at TIMESTAMP(6) WITH TIME ZONE, prior_account_locked BOOLEAN NOT NULL, deleted_email_key VARCHAR(64));
CREATE TABLE IF NOT EXISTS account_deletion_otp_challenges (id UUID PRIMARY KEY, user_id UUID NOT NULL, created_at TIMESTAMP(6) WITH TIME ZONE NOT NULL, expires_at TIMESTAMP(6) WITH TIME ZONE NOT NULL, resend_after TIMESTAMP(6) WITH TIME ZONE NOT NULL, attempts INTEGER NOT NULL, consumed BOOLEAN NOT NULL, verified BOOLEAN NOT NULL, otp_hash VARCHAR(64), version BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS offline_transaction_logs (id UUID PRIMARY KEY, owner_user_id UUID NOT NULL, customer_upi_id VARCHAR(80) NOT NULL, merchant_upi_id VARCHAR(255) NOT NULL, amount DECIMAL(19,2) NOT NULL, local_timestamp TIMESTAMP(6) NOT NULL, bluetooth_txn_id VARCHAR(128) NOT NULL UNIQUE, sync_status VARCHAR(16) NOT NULL, received_at TIMESTAMP(6) WITH TIME ZONE NOT NULL);
CREATE TABLE IF NOT EXISTS saved_recipients (id UUID PRIMARY KEY, owner_user_id UUID NOT NULL, recipient_user_id UUID NOT NULL, saved_at TIMESTAMP(6) WITH TIME ZONE NOT NULL, CONSTRAINT uk_saved_recipient_owner_target UNIQUE(owner_user_id, recipient_user_id));
